use crate::{msjz04 as m,catalog,model::*,unit_support::*};
fn layout()->Game{let mut g=game();g.players[0].society_zone.card=Some(g.make_card(m::ID,0));g}
fn top(g:&mut Game){for _ in 0..32{if g.pending.is_some()||g.stack.is_empty(){return;}crate::jc029_tests::pass_top(g);}panic!("unsettled stack");}
fn constructed(seed:u64)->Game{let mut d=crate::deck::preset("watchers").unwrap();d.id="closed-msjz04".into();d.society_id=Some(m::ID.into());d.core_card_id=None;d.cards=[("JZ58",3),("JZ31",3),("JC042",3),("BQ049",3),("JC125",38)].into_iter().map(|(id,count)|catalog::DeckEntry{card_id:id.into(),count}).collect();assert!(crate::deck::validate(d.clone()).is_err());let mut societies=catalog::catalog().societies.clone();societies.iter_mut().find(|s|s.card.id==m::ID).unwrap().card.supported=true;let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id=="BQ049").unwrap().supported=true;let d=crate::deck::validate_with_registry(d,&cards,&societies).unwrap();let mut other=crate::deck::preset("watchers").unwrap();other.society_id=None;other.core_card_id=None;other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=crate::deck::validate(other).unwrap();let mut g=Game::new("msjz04".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d,other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();g}
#[test]fn msjz04_original_red_purple_neutral_closed(){let s=crate::society::definition(m::ID).unwrap();assert!(!s.card.supported);assert_eq!(s.card.color,"红");assert_eq!(s.starting_hand,6);let e=|id:&str|vec![catalog::DeckEntry{card_id:id.into(),count:1}];for id in ["JZ58","JZ31","JC125"]{assert!(crate::society::validate_construction(&s,&e(id),&catalog::catalog().cards).is_ok());}assert!(crate::society::validate_construction(&s,&e("JC001"),&catalog::catalog().cards).is_err());}
#[test]fn msjz04_real_pre_hand_seal_unique_name_then_draw_and_restore(){for empty in [true,false]{let mut g=constructed(8);assert!(g.players[0].hand.is_empty());let p=g.pending.clone().unwrap();assert!(matches!(p.resolution,ChoiceResolution::MSJZ04Opening{seat:0}));assert_eq!(p.choice.options.len(),3);let ids=p.choice.options.iter().map(|o|o.id.clone()).collect::<Vec<_>>();reject(&mut g,0,Action{choice_id:Some(p.choice.id.clone()),selected:Some(ids[..2].to_vec()),..Action::new("choose")});choose(&mut g,if empty{vec![]}else{vec![ids[0].clone()]});assert_eq!(g.players[0].hand.len(),6);assert_eq!(g.sealed_cards.len(),usize::from(!empty));assert_eq!(g.players[0].deck.len(),44-usize::from(!empty));restore(&mut g);}}
#[test]fn msjz04_real_host_death_paid_sealed_release_is_hidden(){let mut g=layout();fund(&mut g,0,"JC125",1);let c=g.make_card("JZ58",0);g.seal_card_on_valid_host(c,0,"society:p0");let host=field(&mut g,"JZ31",0);g.remove_dead(&host,RemovalCause::Sacrifice);g.drive().unwrap();assert!(g.pending.is_some());until_pay(&mut g);assert_eq!(g.resources(0),1);choose(&mut g,vec!["pay".into()]);let p=g.pending.clone().unwrap();assert_eq!(p.choice.kind,"sealed");choose(&mut g,vec![p.choice.options[0].id.clone()]);assert_eq!(g.resources(0),0);assert!(g.sealed_cards.is_empty());let c=g.regions[0].cards.iter().find(|c|c.definition=="JZ58").unwrap();assert!(c.face_down);assert_eq!(c.controller,0);restore(&mut g);}
#[test]fn msjz04_nonhost_enemy_or_hidden_death_does_not_observe(){for mode in 0..3{let mut g=layout();let id=field(&mut g,if mode==0{"JC125"}else{"JZ31"},if mode==1{1}else{0});if mode==2{g.board_mut(&id).unwrap().face_down=true;}g.remove_dead(&id,RemovalCause::Sacrifice);g.drive().unwrap();assert!(g.pending.as_ref().is_none_or(|p|!matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==m::DEATH)));restore(&mut g);}}

fn until_pay(g:&mut Game){for _ in 0..80{if let Some(p)=g.pending.clone(){if matches!(p.resolution,ChoiceResolution::Frame{choice:FrameChoice::MSJZ04Pay,..}){return;}let selected=if matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if d.ability.key==m::DEATH){vec!["accept".into()]}else{p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()};choose(g,selected);}else if !g.stack.is_empty(){top(g);}else{g.drive().unwrap();}}panic!("payment not reached");}
fn bad(reference:&Game,g:&Game){let raw=serde_json::to_string(g).unwrap();assert!(Game::from_persisted(&raw).is_err());let mut r=crate::jc029_tests::envelope(reference);r.game=g.clone();assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&r).unwrap()).is_err());}
#[test]fn msjz04_corrupt_opening_and_payment_rejected(){let g=constructed(4);for n in 0..5{let mut x=g.clone();match n{0=>x.pending=None,1=>x.pending.as_mut().unwrap().seat=1,2=>x.pending.as_mut().unwrap().choice.max=Some(6),3=>x.pending.as_mut().unwrap().choice.options.clear(),_=>x.effects.push_back(Effect::MSJZ04Opening{seat:0})}bad(&g,&x);}let mut g=layout();fund(&mut g,0,"JC125",1);let c=g.make_card("JZ58",0);g.seal_card_on_valid_host(c,0,"society:p0");let id=field(&mut g,"JZ31",0);g.remove_dead(&id,RemovalCause::Sacrifice);g.drive().unwrap();until_pay(&mut g);for n in 0..5{let mut x=g.clone();let p=x.pending.as_mut().unwrap();match n{0=>p.seat=1,1=>p.choice.min=Some(1),_=>{let ChoiceResolution::Frame{frame,..}=&mut p.resolution else{panic!()};match n{2=>frame.source.card.definition="MSJC04".into(),3=>frame.steps.clear(),_=>x.effects.push_back(Effect::Frame{frame:frame.clone()})}}}bad(&g,&x);}restore(&mut g);}
#[test]fn msjz04_declining_effect_payment_or_changed_region_never_releases(){for mode in 0..2{let mut g=layout();fund(&mut g,0,"JC125",1);let c=g.make_card("JZ58",0);g.seal_card_on_valid_host(c,0,"society:p0");let id=field(&mut g,"JZ31",0);g.remove_dead(&id,RemovalCause::Sacrifice);g.drive().unwrap();until_pay(&mut g);if mode==0{choose(&mut g,vec![]);assert_eq!(g.resources(0),1);}else{g.regions[0].card=g.make_card("DQJC115",0);choose(&mut g,vec!["pay".into()]);assert_eq!(g.resources(0),0);}assert_eq!(g.sealed_cards.len(),1);assert!(!g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="JZ58"));restore(&mut g);}}

fn selections(g:&Game,p:&Pending,pay:bool)->Vec<String>{match &p.resolution{
 ChoiceResolution::MSJZ04Opening{..}=>p.choice.options.iter().take(1).map(|o|o.id.clone()).collect(),
 ChoiceResolution::Declare{declaration:d,..}if d.ability.key==m::DEATH=>vec!["accept".into()],
 ChoiceResolution::Frame{choice:FrameChoice::MSJZ04Pay,..}=>if pay{vec!["pay".into()]}else{vec![]},
 ChoiceResolution::Frame{choice:FrameChoice::MSJZ04Release,..}=>vec![p.choice.options[0].id.clone()],
 ChoiceResolution::Frame{choice:FrameChoice::BQ049Sacrifice,..}=>vec![p.choice.options.iter().find(|o|g.board(&o.id).is_some_and(|(_,c)|c.definition=="JZ31")).unwrap().id.clone()],
 _=>{let mut options=p.choice.options.iter().collect::<Vec<_>>();options.sort_by_key(|o|g.players[p.seat].hand.iter().any(|c|c.id==o.id&&matches!(c.definition.as_str(),"JZ31"|"BQ049")));options.into_iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect()}
}}
fn duplicate(mut v:serde_json::Value)->serde_json::Value{for s in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(s["expected"]["state"].as_str().unwrap()).unwrap();let d=r.transition(s["seat"].as_u64().unwrap()as usize,Some(serde_json::from_value(s["command"].clone()).unwrap()),0).unwrap();assert_eq!(d.outcome,"rejected");assert_eq!(d.state,s["expected"]["state"]);assert!(!d.changed&&d.journal.is_empty());s["duplicate"]=serde_json::to_value(d).unwrap();}v}
fn natural()->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(seed,g)=(1..1025).find_map(|seed|{let g=constructed(seed);let mut probe=g.clone();while let Some(p)=probe.pending.clone(){let ids=selections(&probe,&p,true);choose(&mut probe,ids);}let h=&probe.players[0].hand;["BQ049","JZ31","JC042"].iter().all(|id|h.iter().any(|c|c.definition==*id)).then_some((seed,g))}).expect("bounded dealt host/command/red asset hand");let deck=g.players[0].deck_snapshot.clone().unwrap();let mut t=Trace::new_preserving_rng(g,"msjz04-natural-opening-host-sacrifice-and-release".into(),750);let mut played=false;let mut released=false;for _ in 0..1800{if let Some(p)=t.room.game.pending.clone(){let ending=matches!(p.resolution,ChoiceResolution::Frame{choice:FrameChoice::MSJZ04Release,..});let ids=selections(&t.room.game,&p,true);t.choose(ids);if ending{released=true;}continue;}if released&&t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}let g=&t.room.game;let legal=g.legal_actions(0);let host=g.regions.iter().flat_map(|r|&r.cards).any(|c|c.definition=="JZ31"&&c.controller==0&&!c.face_down);let a=if g.players[0].assets.len()<6{let red=g.players[0].assets.iter().any(|c|c.definition=="JC042");legal.iter().find(|a|a.action.kind=="asset"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&if red{c.definition=="JC125"}else{c.definition=="JC042"})))}else if !host&&!played{legal.iter().find(|a|a.action.kind=="deploy"&&a.action.card_id.as_ref().is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition=="JZ31")))}else if host&&!played{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::bq049::KEY)&&a.action.option.as_deref()==Some("sacrifice"))}else{None};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(crate::bq049::KEY){played=true;}t.action(0,a.action.clone());}else{t.pass();}}
 assert!(released&&played,"natural release did not finish");let c=t.room.game.regions.iter().flat_map(|r|&r.cards).find(|c|c.definition=="JZ58").unwrap();assert!(c.face_down&&c.controller==0);assert!(t.room.game.sealed_cards.is_empty());let mut v=t.value();v["construction"]=serde_json::json!({"deck":deck,"seed":seed,"privateRegistryOnly":true,"privateRegistryCandidates":[m::ID,"BQ049"],"noLayoutOrResourceMutation":true});duplicate(v)}
fn prepared(pay:bool,index:usize)->serde_json::Value{use crate::abi112_review_play_tests::Trace;let mut g=layout();fund(&mut g,0,"JC125",1);let c=g.make_card("JZ58",0);g.seal_card_on_valid_host(c,0,"society:p0");let host=field(&mut g,"JZ31",0);g.remove_dead(&host,RemovalCause::Sacrifice);g.drive().unwrap();let mut t=Trace::new_preserving_rng(g,format!("msjz04-prepared-{}",if pay{"pay"}else{"decline"}),index);for _ in 0..100{if let Some(p)=t.room.game.pending.clone(){let ids=selections(&t.room.game,&p,pay);t.choose(ids);}else if t.room.game.stack.is_empty()&&t.room.game.effects.is_empty(){break;}else{t.pass();}}assert_eq!(t.room.game.resources(0),u32::from(!pay));assert_eq!(t.room.game.sealed_cards.len(),usize::from(!pay));duplicate(t.value())}
#[test]fn msjz04_native_natural_and_prepared_room_export(){let cases=vec![natural(),prepared(true,751),prepared(false,752)];let mut binding=crate::bq052_tests::source_bindings();use sha2::{Digest,Sha256};for(n,bytes)in[("rust-game/src/msjz04.rs",include_bytes!("msjz04.rs").as_slice()),("rust-game/src/msjz04_tests.rs",include_bytes!("msjz04_tests.rs").as_slice()),("rust-game/src/society.rs",include_bytes!("society.rs").as_slice()),("rust-game/src/death_observers.rs",include_bytes!("death_observers.rs").as_slice())]{binding["files"][n]=serde_json::json!(format!("{:x}",Sha256::digest(bytes)));}if let Ok(p)=std::env::var("MSJZ04_NATIVE_OUT"){std::fs::write(p,serde_json::to_vec(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":binding,"cases":cases})).unwrap()).unwrap();}}

#[test]fn msjz04_release_obeys_existing_hidden_entry_slow_and_privacy(){let mut g=layout();fund(&mut g,0,"JC125",1);let a=g.make_card("WM044",1);g.attachments.push(Attachment{card:a,host_id:"society:p1".into()});let c=g.make_card("JZ58",0);g.seal_card_on_valid_host(c,0,"society:p0");let id=field(&mut g,"JZ31",0);g.remove_dead(&id,RemovalCause::Sacrifice);g.drive().unwrap();until_pay(&mut g);choose(&mut g,vec!["pay".into()]);let pick=g.pending.as_ref().unwrap().choice.options[0].id.clone();choose(&mut g,vec![pick]);let c=g.regions[0].cards.iter().find(|c|c.definition=="JZ58").unwrap();assert!(c.face_down&&c.exhausted);assert!(!g.players[0].conceal_used);for viewer in 1..4{assert!(g.card_view(c,viewer,Some(0),None).card_id.is_none());}restore(&mut g);}
